using System;
using System.Linq;
using System.Threading;
using ChameLab.Models;
using ChameLab.Services;
using Crapto1Sharp;
using Xunit;

namespace ChameLab.Tests;

public class StaticEncryptedNestedRecoveryTests
{
    [Fact]
    public void ReferenceCExample_MatchesEntireSortedCandidateSet()
    {
        // Generated by Reference/static_encrypted_vectors.c from the original C solvers.
        var keys = StaticEncryptedNestedRecovery.Recover(0xA13E4902, new NestedNonce(0xD14191B3, 0x2E9E49FC, 15));
        Assert.Equal(44075, keys.Count);
        ulong hash = 14695981039346656037UL;
        foreach (var key in keys.Order())
            for (var j = 0; j < 6; j++)
                hash = unchecked((hash ^ ((key >> (8 * j)) & 255)) * 1099511628211UL);
        Assert.Equal(0x79007A0A206AF947UL, hash);
    }

    [Theory]
    [InlineData(0xD14191B3u, 0x112233445566UL, 0x0E97)]
    [InlineData(0x12345678u, 0xFFFFFFFFFFFFUL, 0x51E0)]
    [InlineData(0x00010000u, 0UL, 0xB0F2)]
    [InlineData(0u, 0UL, 0x64B0)]
    public void Seed_MatchesOriginalC(uint nt, ulong key, int expected)
        => Assert.Equal((ushort)expected, StaticEncryptedNestedRecovery.Seed(nt, key));

    [Theory]
    [InlineData(0UL)]
    [InlineData(0xFFFFFFFFFFFFUL)]
    [InlineData(0x112233445566UL)]
    public void SingleNonce_RecoversKeyAndFiltersLastEncryptedParity(ulong key)
    {
        const uint uid = 0xA13E4902, nt = 0xD14191B3;
        var state = new Crypto1State(key);
        var enc = nt ^ Crypto1.Crypto1Word(ref state, uid ^ nt, false);
        var stream = (Crypto1.Crypto1Word(ref state, 0, false) >> 24) & 1;
        var error = (byte)(Crypto1.OddParity8((byte)(nt & 255)) ^ Crypto1.OddParity8((byte)enc) ^ stream);
        var keys = StaticEncryptedNestedRecovery.Recover(uid, new NestedNonce(nt, enc, error));
        Assert.Contains(key, keys);
        Assert.DoesNotContain(key, StaticEncryptedNestedRecovery.Recover(uid, new NestedNonce(nt, enc, (byte)(error ^ 1))));
        // Every result must explain the complete captured nonce, not just its parity.
        Assert.All(keys, candidate =>
        {
            var check = new Crypto1State(candidate);
            Assert.Equal(enc, nt ^ Crypto1.Crypto1Word(ref check, uid ^ nt, false));
        });
    }

    [Fact]
    public void EqualNonces_KeepUnfilteredCandidates()
    {
        ulong[] keys = [0, 1, 0xFFFFFFFFFFFF];
        Assert.Same(keys, StaticEncryptedNestedRecovery.Filter(123, keys, 123, []));
    }

    [Fact]
    public void PairFilter_MatchesKnownKeySeed()
    {
        const uint ntA = 0xD14191B3, ntB = 0x12345678;
        const ulong keyB = 0x112233445566;
        var seed = StaticEncryptedNestedRecovery.Seed(ntB, keyB);
        var keys = Enumerable.Range(0, 65536).Select(i => (ulong)i).ToArray();
        var filtered = StaticEncryptedNestedRecovery.Filter(ntA, keys, ntB, [keyB]);
        Assert.NotEmpty(filtered);
        Assert.True(filtered.Count < keys.Length);
        Assert.All(filtered, key => Assert.Equal(seed, StaticEncryptedNestedRecovery.Seed(ntA, key)));
    }

    [Fact]
    public void Cancellation_StopsCalculationAndFiltering()
    {
        var ct = new CancellationToken(true);
        Assert.Throws<OperationCanceledException>(() => StaticEncryptedNestedRecovery.Recover(1, new NestedNonce(2, 3, 4), ct));
        Assert.Throws<OperationCanceledException>(() => StaticEncryptedNestedRecovery.Filter(1, [1], 2, [2], ct));
    }
}

